<?php
// Do not edit this file directly! It is automatically generated after every container start.
class DATABASE_CONFIG {
    public $default = [
        'datasource' => 'Database/MysqlExtended',
        'persistent' => false,
        'host' => '{{ MYSQL_HOST }}',
        'login' => '{{ MYSQL_LOGIN }}',
        'port' => {{ MYSQL_PORT }},
        'password' => {{ MYSQL_PASSWORD | str }},
        'database' => '{{ MYSQL_DATABASE }}',
        'prefix' => '',
        'encoding' => 'utf8mb4 COLLATE utf8mb4_unicode_ci',
{% if MYSQL_USE_TLS %}
        'ssl_ca' => '{{ MYSQL_TLS_CA }}',
{% endif %}
        'settings' => [
            'time_zone' => '"+00:00"',
    {% if MYSQL_SETTINGS -%}
        {% for setting, value in MYSQL_SETTINGS.items() %}
            '{{ setting }}' => '{{ value }}',
        {% endfor %}
    {%- endif %}
        ],
{% if MYSQL_FLAGS or (MYSQL_USE_TLS and not MYSQL_TLS_VERIFY) %}
        'flags' => [
{% if MYSQL_USE_TLS and not MYSQL_TLS_VERIFY %}
            PDO::MYSQL_ATTR_SSL_VERIFY_SERVER_CERT => false,
{% endif %}
    {% for flag, value in (MYSQL_FLAGS or {}).items() %}
            '{{ flag }}' => '{{ value }}',
    {% endfor %}
        ]
{% endif %}
    ];
}
